n=10; q=13
edges=[]
for g in range(5): edges.append((2*g,2*g+1))
for g in range(4):
    for i in range(2): edges.append((2*g+i,2*(g+1)+i))
adj=[set() for _ in range(n)]
for u,v in edges: adj[u].add(v); adj[v].add(u)

def solve():
    labels=[None]*n; used_labels=set(); used_diffs=set(); nodes=0
    def newdiffs_for(v,l):
        if l in used_labels: return None
        nd=[]; s=set()
        for nb in adj[v]:
            if labels[nb] is not None:
                d=abs(l-labels[nb])
                if d==0 or d in used_diffs or d in s: return None
                s.add(d); nd.append(d)
        return nd
    def rec(count):
        nonlocal nodes
        nodes+=1
        if count==n:
            if used_diffs==set(range(1,14)):
                return labels.copy()
            return None
        # all assigned edges count: len used_diffs, at final 13. Need diff 13? eventually.
        best=None; best_cands=None; best_key=None
        for v in range(n):
            if labels[v] is None:
                c=[]
                for l in range(q+1):
                    nd=newdiffs_for(v,l)
                    if nd is not None: c.append((l,nd))
                if not c: return None
                ass=sum(labels[nb] is not None for nb in adj[v])
                key=(len(c), -ass, -len(adj[v]))
                if best is None or key<best_key:
                    best=v; best_cands=c; best_key=key
        v=best
        for l,nd in sorted(best_cands, key=lambda x:(min(x[0],q-x[0]), x[0])):
            labels[v]=l; used_labels.add(l)
            for d in nd: used_diffs.add(d)
            res=rec(count+1)
            if res: return res
            for d in nd: used_diffs.remove(d)
            used_labels.remove(l); labels[v]=None
        return None
    res=rec(0)
    return res,nodes
sol,nodes=solve()
print('sol',sol,'nodes',nodes)
if sol:
    diffs=[abs(sol[u]-sol[v]) for u,v in edges]
    print(diffs, sorted(diffs), len(set(diffs)))
